# owner: platform
"""Seating charts: students in rows, sorted by last name."""

from rosterkit.models import Student


def _sort_key(student: Student) -> tuple:
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())


def _row_text(group: list) -> str:
    names = [stud.display_name for stud in group]
    return " | ".join(names)


def _chunk_rows(ordered: list, size: int) -> list:
    lines = []
    for start in range(0, len(ordered), size):
        group = ordered[start : start + size]
        text = _row_text(group)
        lines.append(f"Row {len(lines) + 1}: {text}")
    return lines


# ---
def seating_rows(students: list, seats: int) -> list:
    """Return one text line per row, sorted by last name."""
    if seats < 1:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")
    ordered = sorted(students, key=_sort_key)
    return _chunk_rows(ordered, seats)
